// DHT22 — temperature and humidity on one wire.
//
// The library pulls SDA low to start a read, then times the sensor's 40-bit
// response. Change the sliders in the properties strip and read the values.

#include <DHT.h>

const int DHTPIN = 2;
const int DHTTYPE = DHT22;
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();
  if (isnan(humidity) || isnan(temperature)) {
    Serial.println("DHT read failed");
  } else {
    Serial.print("humidity ");
    Serial.print(humidity);
    Serial.print("%  temperature ");
    Serial.print(temperature);
    Serial.println(" C");
  }
  delay(2000);
}
